import type { Argv, ArgumentsCamelCase, CommandModule } from 'yargs'
import { validateWorkingDir } from '../../util'
import { cwd } from 'process'
import { logger } from '../../logger'
import * as fs from 'fs'
import { NowConfig } from '@servicenow/sdk-build-core'
import { Orchestrator, Project } from '@servicenow/sdk-api'
import chalk from 'chalk'

interface Arguments {
    api: string
    source: string
}

export const explain: CommandModule<unknown, Arguments> = {
    command: 'explain <api> [source]',
    describe: false, // Hidden until ready to ship
    builder: (yargs: Argv) => {
        return yargs
            .positional('api', {
                describe: 'API name to look up (e.g., BusinessRule, Acl)',
                type: 'string',
                demandOption: true,
            })
            .positional('source', {
                describe: `Path to the directory that contains package.json configuration`,
                default: cwd(),
                type: 'string',
            })
    },
    handler: async (args: ArgumentsCamelCase<Arguments>): Promise<void> => {
        try {
            const workingDir = validateWorkingDir(args.source)
            const config = NowConfig.parseFromDirectory(workingDir, fs, logger)
            const project = new Project({ config, fileSystem: fs, rootDir: workingDir, logger })
            const orchestrator = new Orchestrator(project)

            // Get documentation metadata (uses isomorphic resolver)
            const docsMetadata = await orchestrator.getDocsMetadata()

            // Find matching API (case-insensitive)
            const searchTerm = args.api.toLowerCase()
            const matchingEntry = Object.entries(docsMetadata).find(([apiName]) => apiName.toLowerCase() === searchTerm)

            if (!matchingEntry) {
                logger.error(`API "${args.api}" not found`)
                logger.info(`\nAvailable APIs:`)
                Object.keys(docsMetadata).forEach((name) => {
                    logger.info(`  - ${name}`)
                })
                process.exit(1)
            }

            const [apiName, apiDoc] = matchingEntry

            // Read and display the markdown file
            // docPath is already resolved to an absolute path by getDocsMetadata()
            if (!fs.existsSync(apiDoc.docPath)) {
                logger.error(`Documentation file not found: ${apiDoc.docPath}`)
                process.exit(1)
            }

            const markdownContent = fs.readFileSync(apiDoc.docPath, 'utf-8')

            // Display API information header
            console.log('\n' + chalk.cyan('═'.repeat(80)))
            console.log(chalk.bold.cyan(`  ${apiName}`))
            console.log(chalk.cyan('═'.repeat(80)))
            console.log(chalk.gray('Tags:'), chalk.yellow(apiDoc.tags.join(', ')))
            console.log(chalk.cyan('═'.repeat(80)) + '\n')

            // Format and display markdown with syntax highlighting
            const lines = markdownContent.split('\n')
            let inCodeBlock = false

            for (let line of lines) {
                // Code block markers
                if (line.startsWith('```')) {
                    inCodeBlock = !inCodeBlock
                    console.log(chalk.dim(line))
                    continue
                }

                // Inside code blocks
                if (inCodeBlock) {
                    console.log(chalk.green(line))
                    continue
                }

                // Headers
                if (line.startsWith('# ')) {
                    console.log(chalk.bold.cyan(line.replace(/^# /, '')))
                    continue
                } else if (line.startsWith('## ')) {
                    console.log('\n' + chalk.bold.yellow(line.replace(/^## /, '')))
                    continue
                } else if (line.startsWith('### ')) {
                    console.log(chalk.bold.white(line.replace(/^### /, '')))
                    continue
                }

                // Format inline markdown
                line = line
                    // Remove markdown links - just show link text
                    .replace(/\[([^\]]+)\]\([^)]+\)/g, chalk.cyan('$1'))
                    // Inline code
                    .replace(/`([^`]+)`/g, chalk.green('$1'))
                    // Bold text
                    .replace(/\*\*([^*]+)\*\*/g, chalk.bold('$1'))
                    // Italic text
                    .replace(/\*([^*]+)\*/g, chalk.italic('$1'))
                    // List items
                    .replace(/^(\s*)([*-])\s/, '$1' + chalk.cyan('•') + ' ')

                console.log(line)
            }
        } catch (error) {
            logger.error(error)
            process.exit(1)
        }
    },
}
